The C++17 implementation uses the historical cowdance.in and cowdance.out files.

```cpp
#include <functional>
#include <fstream>
#include <queue>
#include <vector>
bool feasible(const std::vector<long long> &duration, int k, long long limit) {
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> finish;
    for (int i = 0; i < k; ++i) finish.push(0);
    for (long long d : duration) {
        long long end = finish.top() + d;
        finish.pop();
        if (end > limit) return false;
        finish.push(end);
    }
    return true;
}
int main() {
    std::ifstream in("cowdance.in");
    std::ofstream out("cowdance.out");
    int n;
    long long limit;
    if (!(in >> n >> limit)) return 1;
    std::vector<long long> duration(n);
    for (auto &d : duration) in >> d;
    int lo = 1, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (feasible(duration, mid, limit)) hi = mid;
        else lo = mid + 1;
    }
    out << lo << '\n';
}
```

The following C++17 code uses hps.in and hps.out. Its counts describe FJ’s gestures; a maximum represents Bessie’s winning countergesture, not a matching gesture that would tie.

```cpp
#include <algorithm>
#include <array>
#include <fstream>
#include <vector>
int kind(char ch) { return ch == 'H' ? 0 : ch == 'P' ? 1 : 2; }
int main() {
    std::ifstream in("hps.in");
    std::ofstream out("hps.out");
    int n;
    if (!(in >> n)) return 1;
    std::vector<int> game(n);
    std::array<int, 3> left{0, 0, 0}, right{0, 0, 0};
    for (int &g : game) {
        char ch;
        in >> ch;
        g = kind(ch);
        ++right[g];
    }
    int best = *std::max_element(right.begin(), right.end());
    for (int g : game) {
        ++left[g];
        --right[g];
        int candidate = *std::max_element(left.begin(), left.end())
                      + *std::max_element(right.begin(), right.end());
        best = std::max(best, candidate);
    }
    out << best << '\n';
}
```

This C++17 implementation preserves cowcode.in and cowcode.out and writes exactly one uppercase character.

```cpp
#include <fstream>
#include <string>
int main() {
    std::ifstream in("cowcode.in");
    std::ofstream out("cowcode.out");
    std::string initial;
    long long index;
    if (!(in >> initial >> index)) return 1;
    long long length = static_cast<long long>(initial.size());
    const long long base = length;
    while (length < index) length *= 2;
    while (length > base) {
        long long half = length / 2;
        if (index > half) {
            if (index == half + 1) index = half;
            else index -= half + 1;
        }
        length = half;
    }
    out << initial[static_cast<std::size_t>(index - 1)] << '\n';
}
```
